#!/usr/bin/env bash
# Builds index.html (the website) and worker/engine.mjs (shared scoring engine for the server job) from src/.
set -euo pipefail
cd "$(dirname "$0")/.."
TMP="${TMPDIR:-/tmp}/aca-app.js"
cat src/00-utils.js src/01-core.js src/02-engine.js src/02a-feeds.js src/02b-guide.js src/03-views.js src/04-actions.js src/04a-motion.js src/05-site.js src/06-boot.js > "$TMP"
node --check "$TMP"
{ cat src/head.html; echo '<script src="config.js"></script>'; echo '<script>'; cat "$TMP"; echo '</script>'; echo '</body>'; echo '</html>'; } > index.html
{ echo '// GENERATED by tools/build.sh from src/00-utils.js + src/02-engine.js + src/02a-feeds.js + src/02b-guide.js. Do not edit by hand.';
  cat src/00-utils.js src/02-engine.js src/02a-feeds.js src/02b-guide.js
  echo 'export { uid, nowISO, clone, esc, uniqCI, splitList, clamp, sum, pct, lpa, lpaNum, salaryRange, fmtDate, stableStringify, DEFAULT_WEIGHTS, SOURCE_NAME, STAGES, reached, detectSkills, canonSkill, detectCities, detectWorkMode, detectEmployment, parseSalary, parseExperience, extractJobLocal, scamCheck, scoreJob, category, normalizeUrl, externalId, fingerprint, findDuplicate, analytics, buildReport, candidateYears, isoDay, parseResumeLocal, FEED_API, FEED_OPTS, ATS_NAME, REMOTE_NAME, BOARD_DIRECTORY, directoryBoards, boardsFor, boardKey, parseBoardRef, boardOf, htmlToText, decodeEntities, titleMatcher, levelGate, locationGate, candidateToJob, discoverJobs, checkJobOpen, findDuplicateIn, PRE_APPLY, suggestTitles, suggestPrefs, draftSummary, resumeReview };'
} > worker/engine.mjs
node --check worker/engine.mjs
echo "built index.html ($(wc -c < index.html) bytes) and worker/engine.mjs"
